package vn.edu.eaut.lab6.filter; import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;@WebFilter(urlPatterns={"/students","/student-form.jsp","/student-edit","/student-delete","/dashboard"}) public class AuthFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)a;HttpServletResponse p=(HttpServletResponse)b;HttpSession s=q.getSession(false);if(s!=null&&s.getAttribute("username")!=null)c.doFilter(a,b);else p.sendRedirect(q.getContextPath()+"/login.jsp");}}
